document.documentElement.classList.add('js');
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
const motion = document.querySelector('.motion');
let paused = reduced.matches;
function setMotion(){document.documentElement.classList.toggle('still',paused);motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',paused?'Play animations':'Pause animations');motion.title=paused?'Play animations':'Pause animations';motion.textContent=paused?'▷':'Ⅱ';}
setMotion();motion.addEventListener('click',()=>{paused=!paused;setMotion()});reduced.addEventListener('change',e=>{paused=e.matches;setMotion()});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const target=new Date('2027-01-04T12:00:00+05:30').getTime();
function updateCountdown(){let remaining=Math.max(0,Math.floor((target-Date.now())/1000));const values=[Math.floor(remaining/86400),Math.floor(remaining%86400/3600),Math.floor(remaining%3600/60),remaining%60];['days','hours','minutes','seconds'].forEach((id,i)=>document.getElementById(id).textContent=String(values[i]).padStart(2,'0'));if(remaining===0)document.getElementById('count-note').textContent=Date.now()<target+43200000?'Today is our beautiful beginning!':'Our forever began on 4 January 2027. Thank you for your love.';}
updateCountdown();setInterval(updateCountdown,1000);
for(let i=0;i<9;i++){const p=document.createElement('i');p.className='petal';p.style.left=`${8+i*10}%`;p.style.animationDelay=`${-i*1.4}s`;p.style.animationDuration=`${10+i%3*2}s`;document.querySelector('.petals').append(p)}
document.getElementById('calendar').addEventListener('click',()=>{const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Roshan and Hannath//Wedding//EN','BEGIN:VEVENT','UID:roshan-hannath-20270104@wedding','DTSTAMP:20261117T000000Z','DTSTART:20270104T063000Z','SUMMARY:Roshan & Hannath Wedding Lunch','LOCATION:Namas International Convention Center\\, Thozhuyur','DESCRIPTION:Celebrate the wedding of Roshan Rafeek and Hannath. Lunch at 12 noon IST.','END:VEVENT','END:VCALENDAR'];const url=URL.createObjectURL(new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='Roshan-and-Hannath-Wedding.ics';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
document.getElementById('celebrate').addEventListener('click',()=>{document.getElementById('love-note').textContent='A little love, right back to you! ♡';if(paused||reduced.matches)return;for(let i=0;i<24;i++){const heart=document.createElement('span');heart.className='burst';heart.textContent=i%3?'♡':'♥';heart.style.setProperty('--x',`${(Math.random()-.5)*Math.min(innerWidth,650)}px`);heart.style.setProperty('--y',`${-100-Math.random()*350}px`);heart.style.setProperty('--r',`${(Math.random()-.5)*100}deg`);document.getElementById('confetti').append(heart);setTimeout(()=>heart.remove(),1900)}});
